begin;
-- Do not dispatch test notifications. Every fixture and state change is rolled back.
update reservation_private.settings set enabled=false where id;
do $$
declare g uuid; r uuid; r2 uuid; j uuid; j2 uuid; t text:=public.reservation_telegram_target(); result jsonb; q jsonb; tok uuid; n integer; uid uuid;
begin
 assert t is not null,'staff room configured';
 assert not has_function_privilege('anon','public.apply_reservation_telegram_action(uuid,text,bigint,text,bigint,text)','execute'),'guests cannot approve';
 assert not has_function_privilege('authenticated','public.apply_reservation_telegram_action(uuid,text,bigint,text,bigint,text)','execute'),'players cannot impersonate Telegram staff';
 assert not has_function_privilege('anon','public.reservation_telegram_action_context(uuid,text,bigint)','execute'),'receipt checks are private';
 select id into g from public.reservation_games where is_default_queue for update;
 update public.reservation_games set capacity=(select count(*)+1 from public.reservations where game_id=g and status in ('confirmed','checked_in')) where id=g;
 insert into public.reservations(game_id,player_name,arrival_at) values(g,'ROLLBACK BUTTON TEST',now()+interval '1 hour') returning id,lookup_token into r,tok;
 insert into public.reservations(game_id,player_name,arrival_at) values(g,'ROLLBACK SECOND TEST',now()+interval '1 hour') returning id into r2;
 update reservation_private.outbox set state='sent',message_id=900001,chat_id=t where reservation_id=r returning id into j;
 update reservation_private.outbox set state='sent',message_id=900002,chat_id=t where reservation_id=r2 returning id into j2;
 assert public.reservation_telegram_action_context(j,t,900001),'real receipt accepted';
 assert not public.reservation_telegram_action_context(j,'-999999',900001),'wrong room rejected';
 assert not public.reservation_telegram_action_context(j,t,42),'wrong message rejected';
 result:=public.apply_reservation_telegram_action(j,'-999999',900001,'confirm',123,'TEST STAFF');assert result->>'result'='stale','forged context blocked';
 result:=public.apply_reservation_telegram_action(j,t,900001,'contact',123,'TEST STAFF');assert result->>'result'='contact';
 assert (select status='pending' and contact_required and version=1 from public.reservations where id=r),'contact does not approve booking';
 assert (select contact_required from public.lookup_named_poker_reservation(tok)),'guest sees contact request';
 assert (select telegram_actor_id=123 and telegram_action='contact' from public.reservation_audit where reservation_id=r order by id desc limit 1),'staff actor audited';
 result:=public.apply_reservation_telegram_action(j,t,900001,'confirm',124,'TEST STAFF');assert result->>'result'='stale','old button cannot override newer state';
 select dispatch_token into tok from reservation_private.outbox where reservation_id=r and version=1;
 q:=public.claim_reservation_delivery(tok);assert (q->>'message_id')::bigint=900001,'updates reuse the message';
 assert public.claim_reservation_delivery(tok) is null,'duplicate lease blocked';
 assert public.finish_reservation_delivery((q->>'id')::uuid,(q->>'claim_id')::uuid,900001,null);
 j:=(q->>'id')::uuid;
 result:=public.apply_reservation_telegram_action(j,t,900001,'confirm',123,'TEST STAFF');assert result->>'result'='confirmed','staff can confirm Next 5M without table assignment';
 assert (select status='confirmed' and not contact_required and version=2 from public.reservations where id=r);
 result:=public.apply_reservation_telegram_action(j,t,900001,'confirm',123,'TEST STAFF');assert result->>'result'='stale','repeat callback cannot duplicate approval';
 assert (select count(*)=2 from public.reservation_audit where reservation_id=r),'one audit per action';
 result:=public.apply_reservation_telegram_action(j2,t,900002,'confirm',123,'TEST STAFF');assert result->>'result'='full','last seat protected';
 select dispatch_token into tok from reservation_private.outbox where reservation_id=r and version=2;
 q:=public.claim_reservation_delivery(tok);assert public.finish_reservation_delivery((q->>'id')::uuid,(q->>'claim_id')::uuid,900001,null);j:=(q->>'id')::uuid;
 result:=public.apply_reservation_telegram_action(j,t,900001,'confirm',123,'TEST STAFF');assert result->>'result'='unchanged','current confirmed button is idempotent';
 result:=public.apply_reservation_telegram_action(j,t,900001,'contact',123,'TEST STAFF');assert result->>'result'='contact';
 select user_id into uid from public.user_profiles where role='admin' and active limit 1;
 perform set_config('request.jwt.claim.sub',uid::text,true);
 assert public.review_poker_reservation(r,'confirmed',3),'web staff can resolve contact flag';
 assert (select not contact_required from public.reservations where id=r);
 update public.reservation_games set is_open=false where id=g;
 result:=public.apply_reservation_telegram_action(j2,t,900002,'confirm',123,'TEST STAFF');assert result->>'result'='closed';
 update public.reservations set status='cancelled' where id=r2;
 select id into j2 from reservation_private.outbox where reservation_id=r2 and version=1;
 update reservation_private.outbox set state='sent',message_id=900002,chat_id=t where id=j2;
 result:=public.apply_reservation_telegram_action(j2,t,900002,'confirm',123,'TEST STAFF');assert result->>'result'='inactive','cancelled bookings stay cancelled';
 assert reservation_private.dispatch()=0,'no test alerts sent';
end $$;
rollback;
